package txallo

import (
	"crypto/sha256"
	"encoding/hex"
	"encoding/json"
	"math"
	"os"
	"reflect"
	"strings"
	"testing"
)

// These expectations were generated by running the original ContribChain
// source files, not this adapter, in a separate temporary Go module. Their
// source digests and generation procedure are recorded in the fixture.
func TestContribChainSourceOracle(t *testing.T) {
	var fixture struct {
		Provenance struct {
			SourceSHA256 map[string]string `json:"sourceSHA256"`
		} `json:"provenance"`
		Cases []struct {
			Name                     string              `json:"name"`
			Shards                   int                 `json:"shards"`
			Beta                     float64             `json:"beta"`
			MaxIterations            int                 `json:"maxIterations"`
			Edges                    [][]json.RawMessage `json:"edges"`
			ExpectedPlacement        map[string]uint64   `json:"expectedPlacement"`
			ExpectedCommunityCount   int                 `json:"expectedCommunityCount"`
			ExpectedRefinementPasses int                 `json:"expectedRefinementPasses"`
		} `json:"cases"`
	}
	data, err := os.ReadFile("testdata/source_oracle.json")
	if err != nil {
		t.Fatal(err)
	}
	if err := json.Unmarshal(data, &fixture); err != nil {
		t.Fatal(err)
	}
	for name, want := range fixture.Provenance.SourceSHA256 {
		content, err := os.ReadFile("internal/contribchain/" + name)
		if err != nil {
			t.Fatal(err)
		}
		text := strings.TrimPrefix(string(content), "// Adapted from ContribChain-INFOCOM2025; see ../../LICENSE and README_zh.md.\n")
		text = strings.Replace(text, "package contribchain", "package louvain", 1)
		digest := sha256.Sum256([]byte(text))
		if hex.EncodeToString(digest[:]) != want {
			t.Fatalf("upstream core %s no longer matches the audited source", name)
		}
	}
	if len(fixture.Cases) < 6 {
		t.Fatal("missing source oracle cases")
	}
	for _, tc := range fixture.Cases {
		t.Run(tc.Name, func(t *testing.T) {
			g := NewGraph()
			for _, e := range tc.Edges {
				var from, to string
				var count int
				if err := json.Unmarshal(e[0], &from); err != nil {
					t.Fatal(err)
				}
				if err := json.Unmarshal(e[1], &to); err != nil {
					t.Fatal(err)
				}
				if err := json.Unmarshal(e[2], &count); err != nil {
					t.Fatal(err)
				}
				for i := 0; i < count; i++ {
					if err := g.AddTransaction(from, to); err != nil {
						t.Fatal(err)
					}
				}
			}
			current := map[string]uint64{}
			for i, label := range g.Vertices() {
				current[label] = uint64(i % tc.Shards)
			}
			result, err := Optimize(g, current, Config{tc.Shards, tc.Beta, tc.MaxIterations})
			if err != nil {
				t.Fatal(err)
			}
			if !reflect.DeepEqual(result.Placement, tc.ExpectedPlacement) {
				t.Fatalf("placement differs from original source: got %v want %v", result.Placement, tc.ExpectedPlacement)
			}
			if result.CommunityCount != tc.ExpectedCommunityCount || result.RefinementPasses != tc.ExpectedRefinementPasses {
				t.Fatalf("source phase counters differ: got communities=%d passes=%d; want %d %d", result.CommunityCount, result.RefinementPasses, tc.ExpectedCommunityCount, tc.ExpectedRefinementPasses)
			}
			assertCountConservation(t, result.Before)
			assertCountConservation(t, result.After)
			// Planning must not mutate or reset the completed-transaction graph.
			if g.LogicalTransactions() != result.GraphTransactions {
				t.Fatal("optimizer mutated input counts")
			}
		})
	}
}

func assertCountConservation(t *testing.T, m Metrics) {
	t.Helper()
	var inner, cross uint64
	for _, load := range m.ShardLoads {
		inner += load.InnerTransactions
		cross += load.CrossIncidentTransactions
	}
	if cross != 2*m.CrossTransactions || inner+m.CrossTransactions != m.LogicalTransactions {
		t.Fatalf("count conservation failed: inner=%d incident=%d cross=%d logical=%d", inner, cross, m.CrossTransactions, m.LogicalTransactions)
	}
}

func TestGraphCountsAndMetrics(t *testing.T) {
	g := NewGraph()
	for _, edge := range [][2]string{{"a", "b"}, {"b", "a"}, {"b", "c"}} {
		if err := g.AddTransaction(edge[0], edge[1]); err != nil {
			t.Fatal(err)
		}
	}
	if g.VertexCount() != 3 || g.RelationshipCount() != 2 || g.LogicalTransactions() != 3 {
		t.Fatalf("incorrect aggregate: %+v", g)
	}
	vertices := g.Vertices()
	vertices[0] = "corrupt"
	if g.Vertices()[0] != "a" {
		t.Fatal("Vertices leaks backing storage")
	}
	m := evaluate(g, map[string]uint64{"a": 0, "b": 0, "c": 1}, DefaultConfig(2))
	if m.CrossTransactions != 1 || m.CrossTransactionRate != 1.0/3.0 {
		t.Fatalf("cross rate: %+v", m)
	}
	if m.ShardLoads[0].ModeledLoad != 4 || m.ShardLoads[1].ModeledLoad != 2 || m.MaxModeledLoad != 4 {
		t.Fatalf("count loads: %+v", m.ShardLoads)
	}
	if math.Abs(m.ModeledLoadCV-1.0/3.0) > 1e-12 {
		t.Fatalf("CV: %g", m.ModeledLoadCV)
	}
	assertCountConservation(t, m)
	g.Reset()
	if g.VertexCount() != 0 || g.RelationshipCount() != 0 || g.LogicalTransactions() != 0 {
		t.Fatal("Reset retained graph data")
	}
}

func TestEmptySingleShardAndValidation(t *testing.T) {
	empty, err := Optimize(NewGraph(), nil, DefaultConfig(32))
	if err != nil || len(empty.Placement) != 0 || len(empty.After.ShardLoads) != 32 || empty.After.ModeledLoadCV != 0 {
		t.Fatalf("empty graph: %+v %v", empty, err)
	}
	g := NewGraph()
	if err := g.AddTransaction("a", "b"); err != nil {
		t.Fatal(err)
	}
	r, err := Optimize(g, map[string]uint64{"a": 0, "b": 0}, DefaultConfig(1))
	if err != nil || r.After.CrossTransactions != 0 || r.After.ShardLoads[0].InnerTransactions != 1 || r.RefinementPasses != 0 {
		t.Fatalf("single shard: %+v %v", r, err)
	}
	for _, cfg := range []Config{{0, 2, 70}, {2, -1, 70}, {2, math.NaN(), 70}, {2, math.Inf(1), 70}, {2, math.MaxFloat64, 70}, {2, 2, -1}} {
		if _, err := Optimize(g, map[string]uint64{"a": 0, "b": 1}, cfg); err == nil {
			t.Errorf("accepted bad config %+v", cfg)
		}
	}
	for _, current := range []map[string]uint64{nil, {"a": 0}, {"a": 0, "b": 2}} {
		if _, err := Optimize(g, current, DefaultConfig(2)); err == nil {
			t.Errorf("accepted bad current mapping: %v", current)
		}
	}
	if _, err := Optimize(nil, nil, DefaultConfig(2)); err == nil {
		t.Fatal("accepted nil graph")
	}
	for _, edge := range [][2]string{{"a", "a"}, {"", "a"}, {"a", ""}} {
		if err := g.AddTransaction(edge[0], edge[1]); err == nil {
			t.Errorf("accepted unsupported endpoints %v", edge)
		}
	}
	if g.LogicalTransactions() != 1 || g.VertexCount() != 2 {
		t.Fatal("rejected endpoints mutated graph")
	}
	var nilGraph *Graph
	if err := nilGraph.AddTransaction("a", "b"); err == nil {
		t.Fatal("nil graph did not return error")
	}
	g.transactions = (1 << 23) + 1
	if _, err := Optimize(g, map[string]uint64{"a": 0, "b": 1}, DefaultConfig(2)); err == nil {
		t.Fatal("accepted counts exceeding source float32 precision")
	}
}
